194	/**
195	 * Default configuration for individual account type
196	 * Extends the base config with individual-specific settings
197	 * @type {Object}
198	 */
199	const defaultIndividualConfig = {
200	  ...defaultConfig,
201	  business: {
202	    ...defaultConfig.business,
203	    name: 'Serviço Individual',
204	    type: 'Profissional Autônomo',
205	  },
206	  database: {
207	    ...defaultConfig.database,
208	    dynamodb: {
209	      ...defaultConfig.database.dynamodb,
210	      workersTable: '', // No workers table for individual mode
211	      workersTableArn: '', // No workers ARN for individual mode
212	    }
213	  }
214	};
215	
216	/**
217	 * Default configuration for enterprise account type
218	 * Extends the base config with enterprise-specific settings
219	 * @type {Object}
220	 */
221	const defaultEnterpriseConfig = {
222	  ...defaultConfig,
223	  business: {
224	    ...defaultConfig.business,
225	    name: 'Empresa Multiusuário',
226	    type: 'Empresa de Serviços',
227	  }
228	};
