230	/**
231	 * Context for application configuration
232	 * @type {React.Context}
233	 */
234	const ConfigContext = createContext();
235	
236	/**
237	 * Custom hook to access the configuration context
238	 * @returns {Object} The configuration context
239	 * @throws {Error} If used outside of a ConfigProvider
240	 */
241	export const useConfig = () => {
242	  const context = useContext(ConfigContext);
243	  if (!context) {
244	    throw new Error('useConfig must be used within a ConfigProvider');
245	  }
246	  return context;
247	};
248	
249	/**
250	 * Provider component for configuration context
251	 * Manages state for configuration, authentication, and user roles
252	 * @param {Object} props Component props
253	 * @param {React.ReactNode} props.children Child components
254	 */
255	export function ConfigProvider({ children }) {
256	  /**
257	   * Generates a unique localStorage key for shop-specific configuration
258	   * @param {string} shop - The shop ID (username)
259	   * @returns {string} - The localStorage key for this shop's configuration
260	   */
261	  const getConfigStorageKey = (shop) => `appConfig_${shop || 'default'}`;
262	
263	  // User and shop state
264	  const [userRole, setUserRole] = useState(() => {
265	    try {
266	      return sessionStorage.getItem('userRole') || null;
267	    } catch (error) {
268	      console.error('Error reading userRole from sessionStorage:', error);
269	      return null;
270	    }
271	  });
272	  
273	  const [shopId, setShopId] = useState(() => {
274	    try {
275	      return sessionStorage.getItem('shopId') || null;
276	    } catch (error) {
277	      console.error('Error reading shopId from sessionStorage:', error);
278	      return null;
279	    }
280	  });
281	  
282	  /**
283	   * Initialize config state with saved config or default based on role
284	   * Falls back to role-specific defaults if no saved configuration exists
285	   */
286	  const [config, setConfig] = useState(() => {
287	    try {
288	      const shop = sessionStorage.getItem('shopId');
289	      const storageKey = getConfigStorageKey(shop);
290	      
291	      // First try to load from shop-specific storage key
292	      try {
293	        const saved = localStorage.getItem(storageKey);
294	        if (saved) {
295	          return JSON.parse(saved);
296	        }
297	      } catch (error) {
298	        console.error(`Error reading config from ${storageKey}:`, error);
299	      }
300	  
301	      // If no shop-specific config found, check for legacy 'appConfig' key
302	      try {
303	        const legacyConfig = localStorage.getItem('appConfig');
304	        if (legacyConfig && shop) {
305	          // Migrate legacy config to shop-specific storage
306	          localStorage.setItem(storageKey, legacyConfig);
307	          localStorage.removeItem('appConfig'); // Clean up legacy key
308	          console.log(`Migrated legacy config to ${storageKey}`);
309	          return JSON.parse(legacyConfig);
310	        }
311	      } catch (error) {
312	        console.error('Error migrating legacy config:', error);
313	      }
314	  
315	      // Fallback based on role
316	      const role = sessionStorage.getItem('userRole');
317	      if (role === 'enterprise') return defaultEnterpriseConfig;
318	      if (role === 'individual') return defaultIndividualConfig;
319	      return defaultConfig;
320	    } catch (error) {
321	      console.error('Error initializing config, falling back to default', error);
322	      return defaultConfig;
323	    }
324	  });
325	
326	  const [isAuthenticated, setIsAuthenticated] = useState(false);
327	
328	  /**
329	   * Fetch user session on mount and set authentication state
330	   */
331	  useEffect(() => {
332	    getSession()
333	      .then(session => {
334	        if (!session) return;
335	        
336	        try {
337	          const payload = session.getIdToken().payload;
338	          const username = payload['cognito:username'];
339	          const accountType = payload['custom:accountType'] || 'individual';
340	          
341	          setIsAuthenticated(true);
342	          setUserRole(accountType);
343	          setShopId(username);
344	          
345	          try {
346	            sessionStorage.setItem('userRole', accountType);
347	            sessionStorage.setItem('shopId', username);
348	          } catch (error) {
349	            console.error('Error setting session storage items:', error);
350	          }
351	        } catch (error) {
352	          console.error('Error processing session data:', error);
353	        }
354	      })
355	      .catch((error) => {
356	        // No session => not logged in
357	        console.log('No active session found:', error);
358	      });
359	  }, []);
360	  
361	  /**
362	   * Fetch server-side config when user becomes authenticated or changes role
363	   * Merges remote config with local config
364	   */
365	  useEffect(() => {
366	    if (!isAuthenticated || !shopId) return;
367	    
368	    (async () => {
369	      try {
370	        const remote = await fetchConfig(shopId);  // GET /config?shop_id=shopId
371	        if (remote && Object.keys(remote).length) {
372	          setConfig(prev => ({ ...prev, ...remote }));
373	        }
374	      } catch (err) {
375	        console.error('Could not load remote config → keeping local', err);
376	      }
377	    })();
378	  }, [isAuthenticated, userRole, shopId]);
379	
380	  /**
381	   * Save config to localStorage whenever it changes, using shop-specific key
382	   */
383	  useEffect(() => {
384	    if (!shopId) return;
385	    
386	    try {
387	      const storageKey = getConfigStorageKey(shopId);
388	      console.log(`Saving config for shop=${shopId} to ${storageKey}`);
389	      localStorage.setItem(storageKey, JSON.stringify(config));
390	    } catch (error) {
391	      console.error(`Error saving config to localStorage for shop=${shopId}:`, error);
392	    }
393	  }, [config, shopId]);
394	
395	  /**
396	   * Check for existing authentication on mount
397	   */
398	  useEffect(() => {
399	    try {
400	      const storedRole = sessionStorage.getItem('userRole');
401	      const storedShopId = sessionStorage.getItem('shopId');
402	      
403	      if (storedRole && storedShopId) {
404	        setIsAuthenticated(true);
405	        setUserRole(storedRole);
406	        setShopId(storedShopId);
407	      }
408	    } catch (error) {
409	      console.error('Error checking existing authentication:', error);
410	    }
411	  }, []);
412	
413	  /**
414	   * Authenticate user and set session data
415	   * @param {string} username - User's username
416	   * @param {string} password - User's password
417	   * @returns {Object} Result of login attempt
418	   */
419	  const login = async (username, password) => {
420	    try {
421	      const session = await signIn({ username, password });
422	      if (!session) {
423	        return { success: false, message: 'Failed to get session data' };
424	      }
425	      
426	      try {
427	        const accountType = session.getIdToken().payload['custom:accountType'] || 'individual';
428	        
429	        setIsAuthenticated(true);
430	        setShopId(username);
431	        setUserRole(accountType);
432	        
433	        try {
434	          sessionStorage.setItem('shopId', username);
435	          sessionStorage.setItem('userRole', accountType);
436	        } catch (storageError) {
437	          console.error('Error setting session storage during login:', storageError);
438	        }
439	        
440	        return { success: true };
441	      } catch (parseError) {
442	        console.error('Error parsing session data:', parseError);
443	        return { success: false, message: 'Error processing login response' };
444	      }
445	    } catch (err) {
446	      return { success: false, message: err.message || 'Authentication failed' };
447	    }
448	  };
449	  
450	  /**
451	   * Sign out user and redirect to logout URL
452	   */
453	  const signOut = () => {
454	    try {
455	      // Clear client state
456	      sessionStorage.removeItem('idToken');
457	      sessionStorage.removeItem('shopId');
458	      sessionStorage.removeItem('userRole');
459	    
460	      // Build the exact logout URL Cognito expects
461	      const domain = process.env.REACT_APP_COGNITO_DOMAIN;
462	      const clientId = process.env.REACT_APP_COGNITO_CLIENT_ID;
463	      const logoutUri = process.env.REACT_APP_REDIRECT_URI;
464	      
465	      if (!domain || !clientId || !logoutUri) {
466	        console.error('Missing environment variables for Cognito logout');
467	        window.location.href = '/';
468	        return;
469	      }
470	      
471	      window.location.assign(
472	        `${domain}/logout` +
473	        `?client_id=${clientId}` +
474	        `&logout_uri=${encodeURIComponent(logoutUri)}`
475	      );
476	    } catch (error) {
477	      console.error('Error during sign out:', error);
478	      // Fallback to homepage redirect
479	      window.location.href = '/';
480	    }
481	  };
482	
483	  /**
484	   * Get current user role from state or session storage
485	   * @returns {string|null} The user role
486	   */
487	  const getUserRole = () => {
488	    if (userRole) return userRole;
489	    
490	    try {
491	      return sessionStorage.getItem('userRole') || null;
492	    } catch (error) {
493	      console.error('Error getting user role from session storage:', error);
494	      return null;
495	    }
496	  };
497	
498	  /**
499	   * Update configuration both locally and on the server
500	   * Performs optimistic local update and then syncs with server
501	   * @param {Object} newConfig - The new configuration
502	   */
503	  const updateConfig = async (newConfig) => {
504	    if (!newConfig) {
505	      console.error('Invalid config provided to updateConfig');
506	      return;
507	    }
508	    
509	    try {
510	      // Update local state immediately for responsive UI
511	      setConfig(newConfig);
512	      
513	      // Ensure shop_id is explicitly included in the config
514	      const configWithShopId = { 
515	        ...newConfig, 
516	        shop_id: shopId || sessionStorage.getItem('shopId') || 'default'
517	      };
518	      
519	      // Save to server
520	      await saveConfig(configWithShopId);
521	    } catch (error) {
522	      console.error('Error in updateConfig:', error);
523	      // Note: We don't rollback local state as it's an optimistic update
524	    }
525	  };
526	
527	  /**
528	   * Reset configuration to default based on user role
529	   * Updates both local state and server
530	   */
531	  const resetConfig = async () => {
532	    try {
533	      const role = getUserRole();
534	      let defaultCfg = defaultConfig;
535	      
536	      if (role === 'enterprise') {
537	        defaultCfg = defaultEnterpriseConfig;
538	      } else if (role === 'individual') {
539	        defaultCfg = defaultIndividualConfig;
540	      }
541	
542	      // Ensure shop_id is included
543	      const configWithShopId = {
544	        ...defaultCfg,
545	        shop_id: shopId || sessionStorage.getItem('shopId') || 'default'
546	      };
547	      
548	      // Update local state
549	      setConfig(configWithShopId);
550	      
551	      // Update localStorage with shop-specific key
552	      const currentShopId = shopId || sessionStorage.getItem('shopId');
553	      if (currentShopId) {
554	        const storageKey = getConfigStorageKey(currentShopId);
555	        try {
556	          localStorage.setItem(storageKey, JSON.stringify(configWithShopId));
557	        } catch (storageError) {
558	          console.error(`Error saving reset config to ${storageKey}:`, storageError);
559	        }
560	      }
561	      
562	      // Save to server
563	      await saveConfig(configWithShopId);
564	    } catch (error) {
565	      console.error('Error in resetConfig:', error);
566	    }
567	  };
568	  
569	  // Expose context values
570	  const contextValue = {
571	    config,
572	    updateConfig,
573	    resetConfig,
574	    isAuthenticated,
575	    login,
576	    signOut,
577	    getUserRole,
578	    setUserRole,
579	    shopId
580	  };
581	  
582	  return (
583	    <ConfigContext.Provider value={contextValue}>
584	      {children}
585	    </ConfigContext.Provider>
586	  );
587	}
588	
589	ConfigProvider.propTypes = {
590	  children: PropTypes.node.isRequired,
591	};

