// src/pages/LoginPage.js
import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Container,
  Alert,
  Stack,
  Grid,
  Divider,
} from '@mui/material';
import {jwtDecode} from 'jwt-decode';
import { useConfig } from '../context/ConfigContext';
import AdminPage from './AdminPage';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import EventAvailableIcon from '@mui/icons-material/EventAvailable';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import '../styles/LoginPage.css';

export default function LoginPage() {
  const [error, setError] = useState('');
  const [ready, setReady] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentDate] = useState(new Date());
  const { setUserRole } = useConfig();

  const COGNITO_DOMAIN = process.env.REACT_APP_COGNITO_DOMAIN;
  const COGNITO_CLIENT = process.env.REACT_APP_COGNITO_CLIENT_ID;
  const REDIRECT_URI = process.env.REACT_APP_REDIRECT_URI;
  const SCOPES = 'openid email phone';

  // Generate calendar data for the current month
  const generateCalendarData = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // Get the name of the current month
    const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(
      new Date(year, month, 1)
    );

    // Get the first day of the month
    const firstDay = new Date(year, month, 1).getDay();

    // Get the number of days in the month
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Create an array to store the days
    const days = [];

    // Add empty cells for days before the first day of the month
    for (let i = 0; i < firstDay; i++) {
      days.push(null);
    }

    // Add the days of the month
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(i);
    }

    return { monthName, days };
  };

  const { monthName, days } = generateCalendarData();
  const today = currentDate.getDate();

  // Available days (for demo)
  const availableDays = [3, 8, 12, 15, 19, 22, 26, 29];

  // Called once we have a valid id_token
  const finishLogin = idToken => {
    try {
      const payload = jwtDecode(idToken);
      const accountType = payload['custom:accountType'] || 'individual';
      const username = payload['cognito:username'];

      sessionStorage.setItem('idToken', idToken);
      sessionStorage.setItem('shopId', username);
      sessionStorage.setItem('userRole', accountType);

      setUserRole(accountType);
      setIsLoggedIn(true);
      setReady(true);
    } catch (e) {
      setError('Falha ao processar token: ' + e.message);
      setReady(true);
    }
  };

  // On mount: check for stored token or #id_token in hash
  useEffect(() => {
    // 1) Already logged in?
    const stored = sessionStorage.getItem('idToken');
    if (stored) {
      finishLogin(stored);
      return;
    }

    // 2) Look for id_token in URL hash
    const hash = window.location.hash;
    if (hash.includes('id_token=')) {
      const idToken = new URLSearchParams(hash.slice(1)).get('id_token');
      if (idToken) {
        // remove the hash
        window.history.replaceState({}, document.title, window.location.pathname);
        finishLogin(idToken);
        return;
      } else {
        setError('Nenhum id_token encontrado na resposta.');
      }
    }

    // 3) Not logged in yet — show login button
    setReady(true);
  }, [setUserRole]); // Include setUserRole in dependencies

  // If we have a token and are "ready," show the app
  if (ready && isLoggedIn) {
    return <AdminPage />;
  }

  // Otherwise, show the Entrar button for implicit flow
  const handleHostedUi = () => {
    const params = new URLSearchParams({
      response_type: 'token',
      client_id: COGNITO_CLIENT,
      redirect_uri: REDIRECT_URI,
      scope: SCOPES,
      screen_hint: 'signup', // optional: jump straight to the sign-up form
      lang: 'pt-BR', // Portuguese localization
    });
    window.location.assign(
      `${COGNITO_DOMAIN}/oauth2/authorize?${params.toString()}`
    );
  };

  // Days of the week for the calendar
  const daysOfWeek = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

  return (
    <Box className="login-page-background">
      <Container className="login-container">
        <Paper elevation={5} className="login-card">
          {/* Header */}
          <Box className="login-header">
            <Typography variant="h5" className="login-title">
              Agendamentos Online
            </Typography>
          </Box>

          <Box className="login-body" sx={{ pt: 3, pb: 2 }}>
            {/* Hero Section with Icon and Title - Compact */}
            <Box sx={{ 
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2,
              position: 'relative'
            }}>
              <CalendarMonthIcon 
                color="primary" 
                sx={{ 
                  fontSize: 48, 
                  filter: 'drop-shadow(0 4px 10px rgba(25, 118, 210, 0.3))',
                  animation: 'pulse 2s infinite ease-in-out',
                  mr: 1.5
                }} 
              />
              <Box>
                <Typography 
                  variant="h4" 
                  align="left" 
                  sx={{ 
                    fontWeight: 800, 
                    color: '#1976d2',
                    lineHeight: 1,
                    letterSpacing: '-0.5px',
                    fontSize: { xs: '1.8rem', sm: '2rem' }
                  }}
                >
                  Agendamentos
                </Typography>
                <Typography 
                  variant="subtitle1" 
                  align="left" 
                  sx={{ 
                    fontWeight: 400, 
                    color: '#666',
                    fontSize: '0.9rem'
                  }}
                >
                  simples e eficientes
                </Typography>
              </Box>
            </Box>

            {/* Calendar Preview - Simplified */}
            <Box sx={{ 
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 3,
              gap: 2,
              flexWrap: 'wrap'
            }}>
              {/* Available Days Indicator */}
              <Box sx={{ 
                display: 'flex', 
                flexDirection: 'column',
                alignItems: 'center', 
                gap: 1,
                backgroundColor: 'rgba(25, 118, 210, 0.05)',
                p: 2,
                borderRadius: '8px',
                border: '1px solid rgba(25, 118, 210, 0.1)',
                minWidth: '130px'
              }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 600, color: '#1976d2' }}>
                  Disponível Hoje
                </Typography>
                <Box sx={{ 
                  fontSize: '2rem', 
                  fontWeight: 700, 
                  color: '#00a86b',
                  bgcolor: 'rgba(0, 168, 107, 0.1)',
                  width: '60px',
                  height: '60px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  border: '2px solid rgba(0, 168, 107, 0.2)'
                }}>
                  {today}
                </Box>
                <Typography variant="body2" sx={{ color: '#555' }}>
                  {monthName.charAt(0).toUpperCase() + monthName.slice(1)}
                </Typography>
              </Box>

              {/* Next Available */}
              <Box sx={{ 
                display: 'flex', 
                flexDirection: 'column',
                alignItems: 'center', 
                gap: 1,
                backgroundColor: 'rgba(25, 118, 210, 0.05)',
                p: 2,
                borderRadius: '8px',
                border: '1px solid rgba(25, 118, 210, 0.1)',
                minWidth: '130px'
              }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 600, color: '#1976d2' }}>
                  Horários Livres
                </Typography>
                <Stack direction="row" spacing={1}>
                  {availableDays.slice(0, 3).map((day) => (
                    <Box key={day} sx={{ 
                      fontSize: '1.2rem', 
                      fontWeight: 600, 
                      color: '#00a86b',
                      bgcolor: 'rgba(0, 168, 107, 0.1)',
                      width: '35px',
                      height: '35px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      borderRadius: '50%',
                      border: '1px solid rgba(0, 168, 107, 0.2)'
                    }}>
                      {day}
                    </Box>
                  ))}
                </Stack>
                <Typography variant="body2" sx={{ color: '#555' }}>
                  +{availableDays.length - 3} dias disponíveis
                </Typography>
              </Box>
            </Box>

            {/* Description with Integrated Features */}
            <Box sx={{ mb: 2, textAlign: 'center' }}>
              <Typography 
                variant="body1" 
                sx={{ 
                  mb: 1.5,
                  color: '#444',
                  fontSize: '0.95rem',
                  lineHeight: 1.4
                }}
              >
                Organize sua agenda de forma eficiente com nossa plataforma
              </Typography>

              {/* Features as chips */}
              <Box 
                sx={{ 
                  display: 'flex', 
                  justifyContent: 'center', 
                  gap: 1.5, 
                  flexWrap: 'wrap' 
                }}
              >
                <Box sx={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  bgcolor: 'rgba(25, 118, 210, 0.08)',
                  color: '#1976d2',
                  fontSize: '0.85rem',
                  fontWeight: 500,
                  borderRadius: '16px',
                  py: 0.5,
                  px: 1.2
                }}>
                  <EventAvailableIcon sx={{ mr: 0.5, fontSize: '1rem' }} />
                  Agendamentos Fáceis
                </Box>
                <Box sx={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  bgcolor: 'rgba(25, 118, 210, 0.08)',
                  color: '#1976d2',
                  fontSize: '0.85rem',
                  fontWeight: 500,
                  borderRadius: '16px',
                  py: 0.5,
                  px: 1.2
                }}>
                  <AccessTimeIcon sx={{ mr: 0.5, fontSize: '1rem' }} />
                  Notificações
                </Box>
              </Box>
            </Box>

            {/* Error message */}
            {error && <Alert severity="error" className="errorMessage-customizable">{error}</Alert>}

            {/* Login button */}
            <Button
              onClick={handleHostedUi}
              variant="contained"
              size="large"
              fullWidth
              className="submitButton-customizable"
              startIcon={<EventAvailableIcon />}
            >
              Comece Agora
            </Button>

            {/* Helper text */}
            <Box className="login-footer">
              <Typography variant="body2" className="legalText-customizable">
                Acesse sua conta ou crie uma nova na próxima tela
              </Typography>
            </Box>

            {/* Integrated Footer */}
            <Divider sx={{ mt: 2, mb: 2 }} />

            <Box 
              sx={{ 
                textAlign: 'center',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 1
              }}
            >
              <Box
                component="img"
                src="/images/logo.png"
                alt="Aisol Logo"
                sx={{
                  height: '20px',
                  filter: 'brightness(0) saturate(100%) invert(48%) sepia(79%) saturate(2476%) hue-rotate(86deg) brightness(118%) contrast(119%)' // Green tint
                }}
              />
              <Typography variant="caption" className="legalText-customizable" sx={{ fontSize: '0.75rem' }}>
                Powered by Aisol© 2025
              </Typography>
            </Box>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
}

