// src/components/chat/components/QuickReplyOptions.js
import React from 'react';
import PropTypes from 'prop-types';
import { Box, Button, Chip, Paper, Typography } from '@mui/material';

/**
 * Quick reply options component for guided mode
 */
export function QuickReplyOptions({ 
  step,
  services,
  workers,
  dates,
  times,
  onServiceSelect,
  onWorkerSelect,
  onDateSelect,
  onTimeSelect,
  onConfirm,
  loading
}) {
  // Don't show options if loading
  if (loading) return null;

  // Render appropriate options based on current step
  const renderOptions = () => {
    switch (step) {
      case 2: // Service selection
        return renderServiceOptions();
      case 3: // Worker selection
        return renderWorkerOptions();
      case 4: // Date selection
        return renderDateOptions();
      case 5: // Time selection
        return renderTimeOptions();
      case 6: // Confirmation
        return renderConfirmationOptions();
      default:
        return null;
    }
  };

  // Render service selection options
  const renderServiceOptions = () => {
    if (!services || services.length === 0) return null;

    return (
      <Box>
        <Typography variant="caption" color="text.secondary" mb={1}>
          Serviços disponíveis:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {services.map((service, index) => (
            <Chip
              key={index}
              label={service}
              onClick={() => onServiceSelect(service)}
              clickable
              color="primary"
              variant="outlined"
              sx={{ borderRadius: 1 }}
            />
          ))}
        </Box>
      </Box>
    );
  };

  // Render worker selection options
  const renderWorkerOptions = () => {
    if (!workers || workers.length === 0) return null;

    return (
      <Box>
        <Typography variant="caption" color="text.secondary" mb={1}>
          Profissionais disponíveis:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {workers.map((worker, index) => (
            <Chip
              key={worker.worker_id}
              label={worker.name}
              onClick={() => onWorkerSelect(worker)}
              clickable
              color="primary"
              variant="outlined"
              sx={{ borderRadius: 1 }}
            />
          ))}
        </Box>
      </Box>
    );
  };

  // Render date selection options
  const renderDateOptions = () => {
    if (!dates || dates.length === 0) return null;

    return (
      <Box>
        <Typography variant="caption" color="text.secondary" mb={1}>
          Datas disponíveis:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {dates.map((date, index) => (
            <Chip
              key={index}
              label={formatDateDisplay(date)}
              onClick={() => onDateSelect(date)}
              clickable
              color="primary"
              variant="outlined"
              sx={{ borderRadius: 1 }}
            />
          ))}
        </Box>
      </Box>
    );
  };

  // Render time selection options
  const renderTimeOptions = () => {
    if (!times || times.length === 0) return null;

    return (
      <Box>
        <Typography variant="caption" color="text.secondary" mb={1}>
          Horários disponíveis:
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {times.map((time, index) => (
            <Chip
              key={index}
              label={time}
              onClick={() => onTimeSelect(time)}
              clickable
              color="primary"
              variant="outlined"
              sx={{ borderRadius: 1 }}
            />
          ))}
        </Box>
      </Box>
    );
  };

  // Render confirmation options
  const renderConfirmationOptions = () => {
    return (
      <Box sx={{ display: 'flex', gap: 1 }}>
        <Button
          variant="contained"
          color="primary"
          onClick={() => onConfirm(true)}
          size="small"
        >
          Confirmar
        </Button>
        <Button
          variant="outlined"
          onClick={() => onConfirm(false)}
          size="small"
        >
          Recomeçar
        </Button>
      </Box>
    );
  };

  // Format date for display
  const formatDateDisplay = (dateStr) => {
    try {
      if (!dateStr) return '';

      // Convert YYYY-MM-DD to DD/MM
      const [year, month, day] = dateStr.split('-');
      return `${day}/${month}`;
    } catch (error) {
      console.error('Error formatting date:', error);
      return dateStr;
    }
  };

  return (
    <Paper
      elevation={0}
      sx={{
        p: 1.5, 
        mb: 1,
        borderRadius: 2,
        bgcolor: 'rgba(0,0,0,0.02)',
        border: '1px solid rgba(0,0,0,0.08)'
      }}
    >
      {renderOptions()}
    </Paper>
  );
}

