// src/components/auth/CalendarPreview.js
import React from 'react';
import { Box, Typography, Stack } from '@mui/material';
import { useCalendar } from '../../hooks/useCalendar';

export function CalendarPreview() {
  const { monthName, today, availableDays } = useCalendar();

  return (
    <Box sx={{ 
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      mb: 3,
      gap: 2,
      flexWrap: 'wrap'
    }}>
      {/* Available Days Indicator */}
      <Box sx={{ 
        display: 'flex', 
        flexDirection: 'column',
        alignItems: 'center', 
        gap: 1,
        backgroundColor: 'rgba(25, 118, 210, 0.05)',
        p: 2,
        borderRadius: '8px',
        border: '1px solid rgba(25, 118, 210, 0.1)',
        minWidth: '130px'
      }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 600, color: '#1976d2' }}>
          Disponível Hoje
        </Typography>
        <Box sx={{ 
          fontSize: '2rem', 
          fontWeight: 700, 
          color: '#00a86b',
          bgcolor: 'rgba(0, 168, 107, 0.1)',
          width: '60px',
          height: '60px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          borderRadius: '50%',
          border: '2px solid rgba(0, 168, 107, 0.2)'
        }}>
          {today}
        </Box>
        <Typography variant="body2" sx={{ color: '#555' }}>
          {monthName.charAt(0).toUpperCase() + monthName.slice(1)}
        </Typography>
      </Box>

      {/* Next Available */}
      <Box sx={{ 
        display: 'flex', 
        flexDirection: 'column',
        alignItems: 'center', 
        gap: 1,
        backgroundColor: 'rgba(25, 118, 210, 0.05)',
        p: 2,
        borderRadius: '8px',
        border: '1px solid rgba(25, 118, 210, 0.1)',
        minWidth: '130px'
      }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 600, color: '#1976d2' }}>
          Horários Livres
        </Typography>
        <Stack direction="row" spacing={1}>
          {availableDays.slice(0, 3).map((day) => (
            <Box key={day} sx={{ 
              fontSize: '1.2rem', 
              fontWeight: 600, 
              color: '#00a86b',
              bgcolor: 'rgba(0, 168, 107, 0.1)',
              width: '35px',
              height: '35px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
              border: '1px solid rgba(0, 168, 107, 0.2)'
            }}>
              {day}
            </Box>
          ))}
        </Stack>
        <Typography variant="body2" sx={{ color: '#555' }}>
          +{availableDays.length - 3} dias disponíveis
        </Typography>
      </Box>
    </Box>
  );
}

