 43	      enabled: false,
 44	      campaignId: ''
 45	    }
 46	  };
 47	  
 48	  // Handler for WhatsApp integration changes
 49	  const handleWhatsAppChange = (field, value) => {
 50	    const updatedWhatsApp = {
 51	      ...whatsappConfig,
 52	      [field]: value
 53	    };
 54	    
 55	    updateConfig({
 56	      ...config,
 57	      messaging: {
 58	        ...(config.messaging || {}),
 59	        whatsappIntegration: updatedWhatsApp
 60	      }
 61	    });
 62	  };
 63	  
 64	  // Handler for ad integration changes
 65	  const handleAdIntegrationChange = (field, value) => {
 66	    const updatedAdIntegration = {
 67	      ...whatsappConfig.adIntegration,
 68	      [field]: value
 69	    };
 70	    
 71	    handleWhatsAppChange('adIntegration', updatedAdIntegration);
 72	  };
 73	  
 74	  // Function to handle filter numbers input
 75	  const handleFilterNumbersChange = (e) => {
 76	    const numbersText = e.target.value;
 77	    // Split by commas, new lines, or spaces and filter out empty strings
 78	    const numbersArray = numbersText.split(/[,\n\s]+/).filter(n => n.trim());
 79	    handleWhatsAppChange('filterNumbers', numbersArray);
 80	  };
 81	  
 82	  // Generate a string representation of the filter numbers for the text field
 83	  const getFilterNumbersString = () => {
 84	    return (whatsappConfig.filterNumbers || []).join('\n');
 85	  };
