133	        setQrCodeURL(data.qrcode);
134	        setQrDialogOpen(true);
135	        handleWhatsAppChange('instanceName', instanceName);
136	      } else if (data.base64) {
137	        // Original expected format
138	        setQrCodeURL(data.base64);
139	        setQrDialogOpen(true);
140	        handleWhatsAppChange('instanceName', instanceName);
141	      } else {
142	        throw new Error('QR code not found in response');
143	      }
144	    } catch (error) {
145	      console.error('Error generating QR code:', error);
146	      setQrCodeError(`Falha ao gerar o QR code: ${error.message}`);
