          <IconButton
            color="inherit"
            onClick={handleOpenSettings}
            aria-label="settings"
            sx={{ 
              mr: 1,
              backgroundColor: 'rgba(255, 255, 255, 0.1)',
              '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.2)' }
            }}
          >
            <SettingsIcon />
          </IconButton>

