          return;
        }

        // Check MFA options from user data
        const preferredMfaSetting = userData.PreferredMfaSetting;
        const mfaEnabled = preferredMfaSetting === 'SOFTWARE_TOKEN_MFA';

        resolve(mfaEnabled);
      });
    });
  });
}

