161	  /* ────────────────────────────────────────────────────────────────
162	     4)  APPOINTMENTS – POST
163	     ---------------------------------------------------------------- */
164	  export async function bookAppointment(data) {
165	    // Generate ICS file content for calendar integration
166	    const icsContent = generateIcsFile(data);
167	    
168	    if (isMockMode()) return legacyMockBook(data, icsContent);
169	  
170	    const headers = await authHeader();
171	    const payload = { ...data, shop_id: shopId() };
172	  
173	    const r = await fetch(`${API_BASE}/appointments/book`, {
174	      method: 'POST',
175	      headers,
176	      body: JSON.stringify(payload),
177	    });
178	    if (!r.ok) throw new Error(await r.text());
179	    
180	    // Get the response data
181	    const responseData = await r.json();
182	    
183	    // Add ICS content to the response
184	    return {
185	      ...responseData,
186	      icsContent,
187	      icsFilename: `appointment_${data.date.replace(/\//g, '')}_${data.start_time.replace(':', '')}.ics`
188	    };
189	  }
190	  
191	  /* ────────────────────────────────────────────────────────────────
192	     5)  CUSTOMERS API
193	     ---------------------------------------------------------------- */
194	  export async function fetchCustomers() {
195	    if (isMockMode()) {
196	      return []; // TODO: Add mock customer data when needed
197	    }
198	
199	    try {
200	      const headers = await authHeader();
201	      const r = await fetch(`${API_BASE}/customers?shop_id=${shopId()}`, { headers });
202	      
203	      if (!r.ok) throw new Error(await r.text());
204	      const data = await r.json();
205	      return data.customers || [];
206	    } catch (error) {
207	      console.error('Error fetching customers:', error);
208	      // Return empty array instead of throwing to avoid breaking UI
209	      return [];
210	    }
211	  }
212	  
213	  /* ────────────────────────────────────────────────────────────────
214	     6)  ChatGPT helper
215	     ---------------------------------------------------------------- */
216	  export async function callChatApi(messages) {
217	    if (isMockMode()) {
218	      return Promise.resolve({
219	        response: "This is a mock response. Please configure the OpenAI API to use the chat feature.",
220	        success: true
221	      });
222	    }
223	
224	    try {
225	      // Get config from localStorage
226	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
227	      const storageKey = `appConfig_${shop}`;
228	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
229	      
230	      // Check if OpenAI is enabled and API key exists
231	      if (!cfg.openai?.enabled || !cfg.openai?.apiKey) {
232	        throw new Error('OpenAI is not enabled or API key is missing');
233	      }
234	      
235	      const headers = await authHeader();
236	      
237	      // Use backend proxy instead of direct OpenAI call for security
238	      const response = await fetch(`${API_BASE}/chat`, {
239	        method: 'POST',
240	        headers,
241	        body: JSON.stringify({ 
242	          messages,
243	          shop_id: shopId()
244	        }),
245	      });
246	      
247	      if (!response.ok) {
248	        throw new Error(await response.text());
249	      }
250	      
251	      return await response.json();
252	    } catch (error) {
253	      console.error('Error calling chat API:', error);
254	      return {
255	        error: error.message,
256	        success: false
257	      };
258	    }
259	  }
260	  
261	  /* ────────────────────────────────────────────────────────────────
262	     7)  Legacy local-mock book helper
263	     ---------------------------------------------------------------- */
264	  function legacyMockBook(appt, icsContent) {
265	    // Create a unique ID for this appointment
266	    const appointmentId = appt.id || 
267	      `${appt.date}-${appt.start_time}-${appt.worker_id}-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
268	    
269	    const withId = {
270	      ...appt,
271	      id: appointmentId,
272	      shop_id: shopId(),
273	      created_at: new Date().toISOString(),
274	    };
275	    
276	    // Create a new array instead of mutating the existing one
277	    // This is more thread-safe than directly pushing to the array
278	    const updatedAppointments = [...mockAppointments, withId];
279	    
280	    // Replace the original array with the updated one atomically
281	    mockAppointments.length = 0; 
282	    mockAppointments.push(...updatedAppointments);
283	    
284	    // Persist to localStorage if available
285	    try {
286	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
287	      const storageKey = `mockAppointments_${shop}`;
288	      localStorage.setItem(storageKey, JSON.stringify(updatedAppointments));
289	    } catch (error) {
290	      console.error('Error saving mock appointment to localStorage:', error);
291	    }
292	    
293	    // Generate ICS filename
294	    const icsFilename = `appointment_${appt.date.replace(/\//g, '')}_${appt.start_time.replace(':', '')}.ics`;
295	    
296	    return Promise.resolve({
297	      success: true,
298	      message: 'Appointment saved locally (mock mode)',
299	      id: appointmentId,
300	      icsContent, // Include ICS content in the response
301	      icsFilename // Include ICS filename in the response
302	    });
303	  }
304	  
305	  /* ────────────────────────────────────────────────────────────────
306	     8)  ICS Calendar file generation
307	     ---------------------------------------------------------------- */
308	  function generateIcsFile(appointmentData) {
309	    // Format appointment date and time as YYYYMMDDTHHMMSSZ
310	    const formatDate = (dateStr, timeStr) => {
311	      let date;
312	      
313	      // Handle both YYYY-MM-DD and DD/MM/YYYY formats
314	      if (dateStr.includes('-')) {
315	        // YYYY-MM-DD format
316	        date = new Date(`${dateStr}T${timeStr}:00`);
317	      } else if (dateStr.includes('/')) {
318	        // DD/MM/YYYY format
319	        const [day, month, year] = dateStr.split('/');
320	        date = new Date(`${year}-${month}-${day}T${timeStr}:00`);
321	      } else {
322	        // Invalid date format
323	        console.error('Invalid date format:', dateStr);
324	        // Use current date as fallback
325	        date = new Date();
326	      }
327	      
328	      return date.toISOString().replace(/-|:|\.\d{3}/g, '');
329	    };
330	    
331	    // Start date and duration calculation
332	    const startDate = formatDate(appointmentData.date, appointmentData.start_time);
333	    
334	    // Calculate end time based on duration (default to 30 min if not provided)
335	    const duration = appointmentData.duration || 30;
336	    const startDateObj = new Date(startDate.substring(0, 4) + '-' + 
337	                                 startDate.substring(4, 6) + '-' + 
338	                                 startDate.substring(6, 8) + 'T' + 
339	                                 startDate.substring(9, 11) + ':' + 
340	                                 startDate.substring(11, 13) + ':00Z');
341	    const endDateObj = new Date(startDateObj.getTime() + (duration * 60 * 1000));
342	    const endDate = endDateObj.toISOString().replace(/-|:|\.\d{3}/g, '');
343	    
344	    // Get current timestamp for creation date
345	    const now = new Date().toISOString().replace(/-|:|\.\d{3}/g, '');
346	    
347	    // Get business and appointment details
348	    const config = getDatabaseConfig();
349	    const businessName = config.business?.name || 'Empresa';
350	    const businessAddress = config.business?.address || '';
351	    const serviceName = appointmentData.service_name || 'Consulta';
352	    const workerName = appointmentData.worker_name || 'Profissional';
353	    const customerName = appointmentData.customer_name || 'Cliente';
354	    
355	    // Generate a unique ID for the calendar event
356	    const uid = `${appointmentData.id || Date.now()}@${window.location.hostname || 'booking.app'}`;
357	    
358	    // Create the ICS content following RFC 5545 standard
359	    const icsContent = [
360	      'BEGIN:VCALENDAR',
361	      'VERSION:2.0',
362	      'PRODID:-//AiSol//WhatsApp Booking//PT',
363	      'CALSCALE:GREGORIAN',
364	      'METHOD:PUBLISH',
365	      'BEGIN:VEVENT',
366	      `UID:${uid}`,
367	      `DTSTAMP:${now}`,
368	      `DTSTART:${startDate}`,
369	      `DTEND:${endDate}`,
370	      `SUMMARY:${serviceName} com ${workerName}`,
371	      `DESCRIPTION:Atendimento de ${serviceName} com ${workerName} para ${customerName}`,
372	      `LOCATION:${businessAddress}`,
373	      `ORGANIZER;CN=${businessName}:mailto:noreply@example.com`,
374	      'STATUS:CONFIRMED',
375	      'SEQUENCE:0',
376	      'BEGIN:VALARM',
377	      'TRIGGER:-PT30M',
378	      'ACTION:DISPLAY',
379	      'DESCRIPTION:Lembrete',
380	      'END:VALARM',
381	      'END:VEVENT',
382	      'END:VCALENDAR'
383	    ].join('\r\n');
384	    
385	    return icsContent;
386	  }
387	
388	  /* ────────────────────────────────────────────────────────────────
389	     9)  API service exports
390	     ---------------------------------------------------------------- */
391	  // Only use named exports to maintain consistency
392	  // No default export to avoid import confusion
393

