import axios from 'axios';
import { handleMessage } from '@barber-app/booking-fsm';
import { buildContext } from './fsm-wrapper.js';
import { 
  formatReplyWithOptions, 
  processNumericInput, 
  ContextManager 
} from './numbered-options.js';

// Environment variables
const EVO_BASE = process.env.EVO_BASE_URL;
const EVO_KEY = process.env.EVO_API_KEY;
const PUBLIC_URL = process.env.PUBLIC_API_URL;
const PUBLIC_KEY = process.env.PUBLIC_API_KEY;

// Initialize context manager
const contextManager = new ContextManager();

/**
 * Evolution-API webhook handler for WhatsApp messages
 * @param {Object} event - API Gateway Lambda event
 * @returns {Object} - API Gateway response
 */
export const handler = async (event) => {
  try {
    // Parse the incoming webhook payload
    const payload = JSON.parse(event.body);
    const shopId = payload.instanceId;                // Using instanceId as shop_id
    const phoneNumber = payload.data?.from;
    const rawText = payload.data?.body?.text || '';

    console.log(`Received message from ${phoneNumber}: "${rawText}"`);

    // Create API call headers
    const publicApiHeaders = { 'x-api-key': PUBLIC_KEY };
    const evolutionApiHeaders = { 'apiKey': EVO_KEY };

    // Helper function to check if a number should be allowed based on whitelist/blacklist
    const checkNumberFilter = (number, whatsappConfig) => {
      // If WhatsApp integration is not enabled or config is missing, allow all
      if (!whatsappConfig?.enabled) return true;

      // Check if it's a group message
      const isGroup = number.includes('@g.us');
      if (isGroup && whatsappConfig.disableGroups) {
        console.log(`Blocking message from group chat: ${number}`);
        return { allowed: false, reason: 'group' };
      }

      // Apply number filtering based on whitelist/blacklist
      const filterMode = whatsappConfig.filterMode || 'whitelist';
      const filterNumbers = whatsappConfig.filterNumbers || [];

      // Check if filtering should be applied
      if (filterNumbers.length > 0) {
        // Normalize phone number for comparison
        const normalizedNumber = number.replace(/[^0-9+]/g, '');

        // Check if the number is in the filter list
        const isInList = filterNumbers.some(num => {
          const normalizedFilterNumber = num.replace(/[^0-9+]/g, '');
          return normalizedNumber.includes(normalizedFilterNumber) || 
                normalizedFilterNumber.includes(normalizedNumber);
        });

        // For whitelist: block if NOT in list
        // For blacklist: block if IN list
        const shouldBlock = (filterMode === 'whitelist') ? !isInList : isInList;

        if (shouldBlock) {
          console.log(`Blocking message from ${number} based on ${filterMode} configuration`);
          return { allowed: false, reason: filterMode };
        }
      } else if (filterMode === 'whitelist' && filterNumbers.length === 0) {
        // Empty whitelist means block all (unless it's just not configured)
        console.log(`Blocking message from ${number} - empty whitelist`);
        return { allowed: false, reason: 'emptyWhitelist' };
      }

      console.log(`Message from ${number} allowed by ${filterMode} filter check`);
      return { allowed: true };
    };

    // Get shop config first to check filtering
    let shopConfig;
    try {
      const configResponse = await axios.get(`${PUBLIC_URL}/public/config`, { 
        headers: publicApiHeaders, 
        params: { shop_id: shopId } 
      });
      shopConfig = configResponse.data;

      // Check if this number should be blocked
      const filterResult = checkNumberFilter(phoneNumber, shopConfig?.messaging?.whatsappIntegration);
      if (!filterResult.allowed) {
        return {
          statusCode: 200,
          body: JSON.stringify({ 
            success: true, 
            blocked: filterResult.reason 
          })
        };
      }
    } catch (error) {
      console.error('Error fetching shop config for filtering:', error);
      // Continue processing if we can't check filters
    }

    // Get or create user context
    const contextKey = `${shopId}:${phoneNumber}`;
    let context = contextManager.getContext(shopId, phoneNumber);

    // If no context exists, fetch additional data and create context
    if (!context) {
      try {
        console.log(`Fetching worker data for shop ${shopId}`);

        // Only fetch workers since we already have config
        const workersResponse = await axios.get(`${PUBLIC_URL}/public/workers`, { 
          headers: publicApiHeaders, 
          params: { shop_id: shopId } 
        });

        // Build initial FSM context using the config we already fetched
        context = buildContext(
          shopId,
          shopConfig, // Use the config we already fetched
          workersResponse.data.workers || []
        );

        console.log(`Created initial context for ${phoneNumber}`);
      } catch (error) {
        console.error('Error fetching shop data:', error);
        return {
          statusCode: 500,
          body: JSON.stringify({ error: 'Failed to fetch shop data' })
        };
      }
    }

    // Process numeric input if needed (convert numbers to text options)
    const processedText = processNumericInput(rawText, context);

    if (processedText !== rawText) {
      console.log(`Processed numeric input "${rawText}" to "${processedText}"`);
    }

    // Run the FSM to get the response
    const { reply, context: updatedContext, appointment } = handleMessage(processedText, context);

    // Save the updated context
    contextManager.setContext(shopId, phoneNumber, updatedContext);

    // Format the reply with numbered options
    const formattedReply = formatReplyWithOptions(reply, updatedContext);

    console.log(`Sending reply to ${phoneNumber}: "${formattedReply}"`);

    // If an appointment was created, book it through the public API
    if (appointment) {
      try {
        console.log(`Booking appointment for ${appointment.client_name}`);
        await axios.post(
          `${PUBLIC_URL}/public/appointments/book`,
          { ...appointment, shop_id: shopId },
          { headers: publicApiHeaders }
        );

        // Clear the context after successful booking
        contextManager.deleteContext(shopId, phoneNumber);
        console.log(`Appointment booked successfully, context cleared`);
      } catch (error) {
        console.error('Error booking appointment:', error);
        // Don't fail the request if booking fails, still send the success message
      }
    }

    // Send the reply back to WhatsApp via Evolution API
    try {
      await axios.post(
        `${EVO_BASE}/message/send`,
        {
          instanceId: shopId,
          message: formattedReply,
          chatId: phoneNumber
        },
        { headers: evolutionApiHeaders }
      );

      console.log(`Successfully sent message to ${phoneNumber}`);
    } catch (error) {
      console.error('Error sending WhatsApp reply:', error);
      return {
        statusCode: 500,
        body: JSON.stringify({ error: 'Failed to send WhatsApp reply' })
      };
    }

    return {
      statusCode: 200,
      body: JSON.stringify({ success: true })
    };
  } catch (error) {
    console.error('Unhandled error in webhook handler:', error);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: error.message || 'Internal server error' })
    };
  }
};

import React, { useState } from 'react';
import {
  Paper,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  FormControl,
  FormHelperText,
  Alert,
  Box,
  Button,
  RadioGroup,
  Radio,
  FormLabel,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress
} from '@mui/material';
import QrCodeIcon from '@mui/icons-material/QrCode';
import { useConfig } from '../../../context/ConfigContext';

export default function WhatsAppConfig() {
  const { config, updateConfig } = useConfig();
  const [qrDialogOpen, setQrDialogOpen] = useState(false);
  const [isGeneratingQR, setIsGeneratingQR] = useState(false);
  const [qrCodeURL, setQrCodeURL] = useState('');
  const [qrCodeError, setQrCodeError] = useState('');

  // Initialize whatsappIntegration if it doesn't exist
  const whatsappConfig = config?.messaging?.whatsappIntegration || {
    enabled: false,
    phoneNumber: '',
    instanceName: '',
    filterMode: 'whitelist', // 'whitelist' or 'blacklist'
    filterNumbers: [],
    disableGroups: true,
    adIntegration: {
      enabled: false,
      campaignId: ''
    }
  };

  // Handler for WhatsApp integration changes
  const handleWhatsAppChange = (field, value) => {
    const updatedWhatsApp = {
      ...whatsappConfig,
      [field]: value
    };

    updateConfig({
      ...config,
      messaging: {
        ...(config.messaging || {}),
        whatsappIntegration: updatedWhatsApp
      }
    });
  };

  // Handler for ad integration changes
  const handleAdIntegrationChange = (field, value) => {
    const updatedAdIntegration = {
      ...whatsappConfig.adIntegration,
      [field]: value
    };

    handleWhatsAppChange('adIntegration', updatedAdIntegration);
  };

  // Function to handle filter numbers input
  const handleFilterNumbersChange = (e) => {
    const numbersText = e.target.value;
    // Split by commas, new lines, or spaces and filter out empty strings
    const numbersArray = numbersText.split(/[,\n\s]+/).filter(n => n.trim());
    handleWhatsAppChange('filterNumbers', numbersArray);
  };

  // Generate a string representation of the filter numbers for the text field
  const getFilterNumbersString = () => {
    return (whatsappConfig.filterNumbers || []).join('\n');
  };

  // Generate QR code for WhatsApp connection using Evolution API
  const handleGenerateQR = async () => {
    setIsGeneratingQR(true);
    setQrCodeError('');

    try {
      const phoneNumber = whatsappConfig.phoneNumber.replace(/\D/g, '');
      if (!phoneNumber) {
        throw new Error('Número de telefone é obrigatório');
      }

      // Use the fixed instance name "teste" as shown in the curl command example
      // This is known to work with the Evolution API
      const instanceName = "teste";

      // Using the Evolution API directly with the provided configuration
      const evoBaseUrl = 'https://evolution-api-production-ad04.up.railway.app';
      const evoApiKey = '429683C4C977415CAAFCCE10F7D57E11'; // This would normally be stored in backend

      // Make API call to generate QR code using the format from the curl command:
      // curl -H "apikey:$EVO_KEY" "$EVO_BASE/instance/connect/teste?number=$MY_PHONE"
      const response = await fetch(`${evoBaseUrl}/instance/connect/${instanceName}?number=${phoneNumber}`, {
        method: 'GET',
        headers: {
          'apikey': evoApiKey
        }
      });

      if (!response.ok) {
        throw new Error(`Evolution API responded with status ${response.status}`);
      }

      const data = await response.json();

      console.log("Evolution API response:", data);

      // The API returns the qr string directly in the response
      if (data.qrcode && data.qrcode.base64) {
        // Set QR code from base64 data provided by Evolution API
        setQrCodeURL(data.qrcode.base64);
        setQrDialogOpen(true);

        // Save the instance name for future reference
        handleWhatsAppChange('instanceName', instanceName);
      } else if (data.qrcode) {
        // Just in case it's provided in a different format
        setQrCodeURL(data.qrcode);
        setQrDialogOpen(true);
        handleWhatsAppChange('instanceName', instanceName);
      } else if (data.base64) {
        // Original expected format
        setQrCodeURL(data.base64);
        setQrDialogOpen(true);
        handleWhatsAppChange('instanceName', instanceName);
      } else {
        throw new Error('QR code not found in response');
      }
    } catch (error) {
      console.error('Error generating QR code:', error);
      setQrCodeError(`Falha ao gerar o QR code: ${error.message}`);
    } finally {
      setIsGeneratingQR(false);
    }
  };

  return (
    <Paper sx={{ p: 3, borderRadius: 2, maxHeight: 'calc(100vh - 160px)', overflow: 'auto' }}>
      <Typography variant="h5" gutterBottom>
        Integração com WhatsApp
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Configure sua integração com WhatsApp via Evolution API para atendimento automatizado.
      </Typography>
      <Divider sx={{ my: 3 }} />

      {/* Basic WhatsApp Configuration */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h6" gutterBottom color="primary">
          Configuração Básica
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={whatsappConfig.enabled || false}
                  onChange={(e) => handleWhatsAppChange('enabled', e.target.checked)}
                />
              }
              label="Ativar integração com WhatsApp"
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <TextField
              label="Número de WhatsApp Business"
              fullWidth
              value={whatsappConfig.phoneNumber || ''}
              onChange={(e) => handleWhatsAppChange('phoneNumber', e.target.value)}
              margin="normal"
              disabled={!whatsappConfig.enabled}
              helperText="Formato: +5511999999999"
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <TextField
              label="Provedor de Integração"
              value="Evolution API"
              fullWidth
              disabled
              margin="normal"
              helperText="A integração é realizada via Evolution API"
            />
          </Grid>

          <Grid item xs={12}>
              <Button
                variant="contained"
                color="primary"
                startIcon={<QrCodeIcon />}
                onClick={handleGenerateQR}
                disabled={!whatsappConfig.enabled || isGeneratingQR}
                sx={{ mt: 2 }}
              >
                {isGeneratingQR ? (
                  <>
                    <CircularProgress size={24} color="inherit" sx={{ mr: 1 }} />
                    Gerando QR Code...
                  </>
                ) : (
                  'Gerar QR Code para Conexão'
                )}
              </Button>
              {qrCodeError && (
                <Alert severity="error" sx={{ mt: 2 }}>
                  {qrCodeError}
                </Alert>
              )}
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                Clique para gerar um QR Code que você poderá escanear no WhatsApp para conectar sua conta.
              </Typography>
            </Grid>
        </Grid>
      </Box>

      {/* Advanced WhatsApp Configuration */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h6" gutterBottom color="primary">
          Configuração Avançada
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={whatsappConfig.disableGroups || false}
                  onChange={(e) => handleWhatsAppChange('disableGroups', e.target.checked)}
                  disabled={!whatsappConfig.enabled}
                />
              }
              label="Nunca responder mensagens de grupos"
            />
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Quando ativado, o bot ignorará todas as mensagens enviadas em grupos do WhatsApp.
            </Typography>
          </Grid>

          <Grid item xs={12}>
            <FormControl component="fieldset" sx={{ mt: 2 }} disabled={!whatsappConfig.enabled}>
              <FormLabel component="legend">Modo de Filtragem de Números</FormLabel>
              <RadioGroup
                value={whatsappConfig.filterMode || 'whitelist'}
                onChange={(e) => handleWhatsAppChange('filterMode', e.target.value)}
                row
              >
                <FormControlLabel value="whitelist" control={<Radio />} label="Lista de Permissão" />
                <FormControlLabel value="blacklist" control={<Radio />} label="Lista de Bloqueio" />
              </RadioGroup>
              <FormHelperText>
                {whatsappConfig.filterMode === 'whitelist' 
                  ? 'Lista de Permissão: Apenas os números listados abaixo receberão respostas do bot' 
                  : 'Lista de Bloqueio: Os números listados abaixo nunca receberão respostas do bot'}
              </FormHelperText>
            </FormControl>
          </Grid>

          <Grid item xs={12}>
            <TextField
              label={whatsappConfig.filterMode === 'whitelist' ? 'Números Permitidos' : 'Números Bloqueados'}
              fullWidth
              multiline
              rows={4}
              value={getFilterNumbersString()}
              onChange={handleFilterNumbersChange}
              margin="normal"
              disabled={!whatsappConfig.enabled}
              helperText="Digite um número por linha (formato: +5511999999999)"
              placeholder="+5511999999999&#10;+5511888888888&#10;+5511777777777"
            />
          </Grid>
        </Grid>
      </Box>

      {/* Ads Integration */}
      <Box>
        <Typography variant="h6" gutterBottom color="primary">
          Integração com Anúncios
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={whatsappConfig.adIntegration?.enabled || false}
                  onChange={(e) => handleAdIntegrationChange('enabled', e.target.checked)}
                  disabled={!whatsappConfig.enabled}
                />
              }
              label="Ativar integração com anúncios"
            />
          </Grid>

          <Grid item xs={12}>
            <TextField
              label="ID da Campanha de Anúncios"
              fullWidth
              value={whatsappConfig.adIntegration?.campaignId || ''}
              onChange={(e) => handleAdIntegrationChange('campaignId', e.target.value)}
              margin="normal"
              disabled={!whatsappConfig.enabled || !whatsappConfig.adIntegration?.enabled}
              helperText="ID da campanha de anúncios do Facebook/Instagram"
            />
          </Grid>

          <Grid item xs={12}>
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                A integração com anúncios permite que os usuários que clicarem em um anúncio do tipo 
                &quot;Enviar mensagem&quot; sejam automaticamente atendidos pelo bot. É necessário configurar 
                corretamente a campanha de anúncios no Facebook Ads Manager.
              </Typography>
            </Alert>
          </Grid>
        </Grid>
      </Box>

      {/* QR Code Dialog */}
      <Dialog open={qrDialogOpen} onClose={() => setQrDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Escaneie o QR Code no WhatsApp</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
            {qrCodeURL && (
              <img 
                src={qrCodeURL} 
                alt="WhatsApp QR Code" 
                style={{ maxWidth: '100%', height: 'auto' }} 
              />
            )}
          </Box>
          <Typography variant="body2" align="center">
            Abra o WhatsApp no seu celular, vá em Configurações &gt; Aparelhos conectados &gt; Conectar um aparelho
            e escaneie este QR code.
          </Typography>
          <Alert severity="warning" sx={{ mt: 2 }}>
            Este QR code expira em 45 segundos. Se expirar, feche esta janela e gere um novo.
          </Alert>
          <Alert severity="info" sx={{ mt: 2 }}>
            Após escanear, aguarde até que a conexão seja estabelecida. O sistema receberá e enviará mensagens
            automaticamente uma vez que o status da instância for atualizado para &quot;CONNECTED&quot;.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setQrDialogOpen(false)}>Fechar</Button>
          <Button onClick={handleGenerateQR} color="primary" startIcon={<QrCodeIcon />}>
            Gerar Novo QR Code
          </Button>
