214	  // This is more thread-safe than directly pushing to the array
215	  const updatedAppointments = [...mockAppointments, withId];
216	  
217	  // Replace the original array with the updated one atomically
218	  mockAppointments.length = 0; 
219	  mockAppointments.push(...updatedAppointments);
