    bookingState,
    processGuidedMessage,
    handleServiceSelect,
    handleWorkerSelect,
    handleDateSelect,
    handleTimeSelect,
    handleConfirmation,
    resetBookingState,
    startBookingFlow,
    getAvailableServices
  } = useBookingState(workers, onNewAppointment, addAssistantMessage);

