// src/components/chat/hooks/useGuidedMode.js
import { useState, useCallback, useEffect } from 'react';
import { useConfig } from '../../../context/config';
import { generateDateRange, formatDate, isClosedDay } from '../utils/dateUtils';
import { generateTimeSlots, filterAvailableSlots } from '../utils/bookingUtils';

/**
 * Hook to manage guided mode chat functionality
 * Handles date/time generation and availability
 */
export function useGuidedMode(bookingState, workers, externalFreeModeAllowed = true) {
  const { config } = useConfig();
  const [showServiceOptions, setShowServiceOptions] = useState(false);
  const [showWorkerOptions, setShowWorkerOptions] = useState(false);
  const [showDateOptions, setShowDateOptions] = useState(false);
  const [showTimeOptions, setShowTimeOptions] = useState(false);
  const [availableDates, setAvailableDates] = useState([]);
  const [availableTimes, setAvailableTimes] = useState([]);

  // Check if the OpenAI API is properly configured
  const cfg = useConfig().config;
  const freeModeAvailable = !!(cfg?.openai?.enabled && cfg?.openai?.apiKey);

  // Check if guided mode is enabled in config
  const isGuidedMode = useCallback(() => {
    // If the external freeModeAllowed prop is false, force guided mode
    if (!externalFreeModeAllowed) {
      return true;
    }

    // If OpenAI API is not configured, force guided mode
    if (!freeModeAvailable) {
      return true;
    }

    // Otherwise, respect the configuration
    const guidedMode = config?.chatbot?.guidedMode !== false; // default: guided
    return guidedMode;
  }, [config, freeModeAvailable, externalFreeModeAllowed]);

  // Generate available dates based on business configuration
  const generateDateOptions = useCallback(() => {
    // Default to 14 days from today
    const daysToGenerate = 14;
    const closedDays = config?.business?.closedDays || ['Domingo'];

    // Generate date range
    const dateRange = generateDateRange(daysToGenerate);

    // Filter out closed days
    const availableDates = dateRange
      .filter(date => !isClosedDay(date, closedDays))
      .map(date => formatDate(date));

    // Update available dates state
    setAvailableDates(availableDates);

    return availableDates;
  }, [config]);

  // Generate available times based on business configuration and selected date
  const generateTimeOptions = useCallback((date) => {
    if (!date) return [];

    // Generate time slots based on business hours
    const slots = generateTimeSlots(config, date);

    // TODO: Filter out booked slots based on existing appointments
    const filteredSlots = slots;

    // Update available times state
    setAvailableTimes(filteredSlots);

    return filteredSlots;
  }, [config]);

  // Update options visibility based on booking state
  useEffect(() => {
    if (!isGuidedMode()) {
      // Hide all options in free mode
      setShowServiceOptions(false);
      setShowWorkerOptions(false);
      setShowDateOptions(false);
      setShowTimeOptions(false);
      return;
    }

    // Update options visibility based on current step
    switch (bookingState.step) {
      case 2: // Service selection
        setShowServiceOptions(true);
        setShowWorkerOptions(false);
        setShowDateOptions(false);
        setShowTimeOptions(false);
        break;

      case 3: // Worker selection
        setShowServiceOptions(false);
        setShowWorkerOptions(true);
        setShowDateOptions(false);
        setShowTimeOptions(false);
        break;

      case 4: // Date selection
        setShowServiceOptions(false);
        setShowWorkerOptions(false);
        setShowDateOptions(true);
        setShowTimeOptions(false);

        // Generate date options if not already available
        if (availableDates.length === 0) {
          generateDateOptions();
        }
        break;

      case 5: // Time selection
        setShowServiceOptions(false);
        setShowWorkerOptions(false);
        setShowDateOptions(false);
        setShowTimeOptions(true);

        // Generate time options for the selected date
        if (bookingState.selectedDate) {
          generateTimeOptions(bookingState.selectedDate);
        }
        break;

      default:
        setShowServiceOptions(false);
        setShowWorkerOptions(false);
        setShowDateOptions(false);
        setShowTimeOptions(false);
    }
  }, [bookingState.step, bookingState.selectedDate, isGuidedMode, generateDateOptions, generateTimeOptions, availableDates.length]);

  return {
    isGuidedMode: isGuidedMode(),
    showServiceOptions,
    showWorkerOptions,
    showDateOptions,
    showTimeOptions,
    availableDates,
    availableTimes,
    generateDateOptions,
    generateTimeOptions
  };
}

import React, { useState, useEffect } from 'react';
import {
  Paper,
  Typography,
  Divider,
  Grid,
  TextField,
  Switch,
  FormControlLabel,
  FormHelperText,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Box,
  Alert
} from '@mui/material';
import SmartToyIcon from '@mui/icons-material/SmartToy';
import TipsAndUpdatesIcon from '@mui/icons-material/TipsAndUpdates';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import { useConfig } from '../../../context/config';

export default function AssistantConfig() {
  const { config, updateConfig } = useConfig();
  const [hasOpenAI, setHasOpenAI] = useState(false);

  // Check if OpenAI is configured
  useEffect(() => {
    const isOpenAIConfigured = !!(config?.openai?.enabled && config?.openai?.apiKey);
    setHasOpenAI(isOpenAIConfigured);
  }, [config]);

  // Handler for assistant settings changes
  const handleAssistantChange = (field, value) => {
    updateConfig({
      ...config,
      assistant: {
        ...(config.assistant || {}),
        [field]: value
      }
    });
  };

  // Handler for chatbot settings changes
  const handleChatbotChange = (field, value) => {
    updateConfig({
      ...config,
      chatbot: {
        ...(config.chatbot || {}),
        [field]: value
      }
    });
  };

  // Get default values with fallbacks
  const guidedMode = config?.chatbot?.guidedMode !== false; // default to true
  const dayRange = config?.chatbot?.dayRange || 14; // default to 14 days
  const timeInterval = config?.chatbot?.timeInterval || 15; // default to 15 minutes

  return (
    <Paper sx={{ p: 3, borderRadius: 2, maxHeight: 'calc(100vh - 160px)', overflow: 'auto' }}>
      <Typography variant="h5" gutterBottom>
        Configurações do Assistente Virtual
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Personalize o comportamento e as mensagens do assistente virtual.
      </Typography>
      <Divider sx={{ my: 3 }} />

      {/* Basic Assistant Details */}
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <TextField
            label="Nome do Assistente"
            fullWidth
            value={config?.assistant?.name || ''}
            onChange={(e) => handleAssistantChange('name', e.target.value)}
            margin="normal"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Título do Assistente"
            fullWidth
            value={config?.assistant?.title || ''}
            onChange={(e) => handleAssistantChange('title', e.target.value)}
            margin="normal"
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            label="Título Completo"
            fullWidth
            value={config?.assistant?.fullTitle || ''}
            onChange={(e) => handleAssistantChange('fullTitle', e.target.value)}
            margin="normal"
            helperText="Título completo usado no prompt do assistente"
          />
        </Grid>
      </Grid>
            {/* Greetings & Prompt */}
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <TextField
            label="Mensagem de Boas-vindas"
            fullWidth
            value={config?.assistant?.greeting || ''}
            onChange={(e) => handleAssistantChange('greeting', e.target.value)}
            margin="normal"
            multiline
            rows={2}
          />
        </Grid>

      <Divider sx={{ my: 3 }} />

      {/* Guided Mode Section */}
      <Box sx={{ mb: 4 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <SmartToyIcon sx={{ fontSize: 28, color: 'primary.main', mr: 1.5 }} />
          <Typography variant="h6" color="primary" sx={{ mb: 0 }}>
            Modo de Conversação
          </Typography>
        </Box>

        <FormControlLabel
          control={
            <Switch
              checked={guidedMode}
              onChange={(e) => handleChatbotChange('guidedMode', e.target.checked)}
              color="primary"
            />
          }
          label="Usar modo guiado para agendamentos"
        />
        <FormHelperText>
          {guidedMode ? 
            "O assistente guiará os usuários de forma estruturada no processo de agendamento." :
            "Os usuários poderão conversar livremente com o assistente para agendar horários."}
        </FormHelperText>

        {!hasOpenAI && !guidedMode && (
          <Alert severity="warning" sx={{ mt: 2 }}>
            O modo livre requer configuração da API OpenAI. Sem isso, o sistema usará o modo guiado mesmo com esta opção desativada.
          </Alert>
        )}
      </Box>

      {/* Additional Guided Mode Settings */}
      {guidedMode && (
        <Box sx={{ mb: 4 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <TipsAndUpdatesIcon sx={{ fontSize: 28, color: 'primary.main', mr: 1.5 }} />
            <Typography variant="h6" color="primary" sx={{ mb: 0 }}>
              Configurações do Modo Guiado
            </Typography>
          </Box>

          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <CalendarMonthIcon sx={{ color: 'text.secondary', mr: 1 }} />
                <FormControl fullWidth>
                  <InputLabel id="days-range-label">Período de Datas Disponíveis</InputLabel>
                  <Select
                    labelId="days-range-label"
                    value={dayRange}
                    label="Período de Datas Disponíveis"
                    onChange={(e) => handleChatbotChange('dayRange', e.target.value)}
                  >
                    <MenuItem value={7}>7 dias</MenuItem>
                    <MenuItem value={14}>14 dias</MenuItem>
                    <MenuItem value={21}>21 dias</MenuItem>
                    <MenuItem value={30}>30 dias</MenuItem>
                    <MenuItem value={60}>60 dias</MenuItem>
                  </Select>
                  <FormHelperText>
                    Período de datas futuras que serão exibidas para agendamento
                  </FormHelperText>
                </FormControl>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <AccessTimeIcon sx={{ color: 'text.secondary', mr: 1 }} />
                <FormControl fullWidth>
                  <InputLabel id="time-interval-label">Intervalo de Horários</InputLabel>
                  <Select
                    labelId="time-interval-label"
                    value={timeInterval}
                    label="Intervalo de Horários"
                    onChange={(e) => handleChatbotChange('timeInterval', e.target.value)}
                  >
                    <MenuItem value={5}>5 minutos</MenuItem>
                    <MenuItem value={10}>10 minutos</MenuItem>
                    <MenuItem value={15}>15 minutos</MenuItem>
                    <MenuItem value={20}>20 minutos</MenuItem>
                    <MenuItem value={30}>30 minutos</MenuItem>
                    <MenuItem value={60}>60 minutos</MenuItem>
                  </Select>
                  <FormHelperText>
                    Intervalo entre horários disponíveis para agendamento
                  </FormHelperText>
                </FormControl>
              </Box>
            </Grid>
          </Grid>
        </Box>
      )}



        {/* Only show prompt field if OpenAI is configured */}
        {hasOpenAI && (
          <Grid item xs={12}>
            <TextField
              label="Prompt do Assistente"
              fullWidth
              value={config?.assistant?.prompt || ''}
              onChange={(e) => handleAssistantChange('prompt', e.target.value)}
              margin="normal"
              multiline
              rows={15}
              helperText="Instruções detalhadas para o comportamento do assistente (apenas usado no modo livre)"
            />
          </Grid>
        )}
      </Grid>
    </Paper>
  );
}

