          mb: 1,
          bgcolor: 'primary.main',
          color: 'white',
          borderRadius: '8px 8px 0 0',
          boxShadow: 1
        }}
      >
        <Box
          sx={{
            width: 40,
            height: 40,
            borderRadius: '50%',
            bgcolor: 'primary.light',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '1.2rem',
            fontWeight: 'bold'
          }}
        >
          {config?.assistant?.name?.charAt(0) || 'A'}
        </Box>
        <Box>
