    } else { // Weekdays (Monday-Friday)
      // If no valid weekday hours format, use default
      businessHours = (config?.business?.weekdayHours && config.business.weekdayHours.includes('-')) 
        ? config.business.weekdayHours 
        : '07:00-19:00';
