  1	// src/components/chat/utils/bookingUtils.js
  2	import { addMinutes, isWithinBusinessHours } from './dateUtils';
  3	
  4	/**
  5	 * Create an appointment object from booking state
  6	 * @param {Object} bookingState - Current booking state
  7	 * @returns {Object|null} - Appointment object or null if data is incomplete
  8	 */
  9	export function createAppointmentFromBookingState(bookingState) {
 10	  // Validate required fields
 11	  if (
 12	    !bookingState || 
 13	    !bookingState.clientName || 
 14	    !bookingState.selectedService || 
 15	    !bookingState.selectedDate || 
 16	    !bookingState.selectedTime || 
 17	    !bookingState.selectedWorker
 18	  ) {
 19	    return null;
 20	  }
 21	  
 22	  // Create appointment object
 23	  return {
 24	    id: generateAppointmentId(),
 25	    shop_id: bookingState.shop_id,
 26	    client_name: bookingState.clientName,
 27	    service: bookingState.selectedService,
 28	    worker_id: bookingState.selectedWorker.worker_id,
 29	    worker_name: bookingState.selectedWorker.name,
 30	    date: bookingState.selectedDate,
 31	    start_time: bookingState.selectedTime,
 32	    duration: getDurationForService(bookingState.selectedService, bookingState.config),
 33	    status: 'confirmed',
 34	    created_at: new Date().toISOString()
 35	  };
 36	}
 37	
 38	/**
 39	 * Generate times for a date based on business hours and appointment duration
 40	 * @param {Object} config - Business configuration with hours and duration
 41	 * @param {string} date - Date string in format YYYY-MM-DD
 42	 * @returns {string[]} - Array of available time slots in format HH:MM
 43	 */
 44	export function generateTimeSlots(config, date) {
 45	  // Extract business config values with defaults
 46	  const openHours = config?.business?.openHours || '09:00';
 47	  const closeHours = config?.business?.closeHours || '18:00';
 48	  const lastAppointmentTime = config?.business?.lastAppointmentTime || '17:00';
 49	  const appointmentDuration = config?.business?.appointmentDuration || 30;
 50	  // Use the chatbot timeInterval if available, otherwise fallback to business appointmentInterval
 51	  const appointmentInterval = config?.chatbot?.timeInterval || config?.business?.appointmentInterval || 15;
 52	  
 53	  // Parse start and end times
 54	  const [startHour, startMinute] = openHours.split(':').map(Number);
 55	  
 56	  // Generate all possible time slots
 57	  const slots = [];
 58	  let currentTime = new Date();
 59	  currentTime.setHours(startHour, startMinute, 0, 0);
 60	  
 61	  // Create time slots at intervals until last appointment time
 62	  let reachedEndTime = false;
 63	  while (!reachedEndTime) {
 64	    const timeStr = currentTime.getHours().toString().padStart(2, '0') + 
 65	                    ':' + 
 66	                    currentTime.getMinutes().toString().padStart(2, '0');
 67	    
 68	    // Check if we've passed the last appointment time
 69	    reachedEndTime = !isWithinBusinessHours(timeStr, openHours, lastAppointmentTime);
 70	    if (reachedEndTime) {
 71	      break;
 72	    }
 73	    
 74	    slots.push(timeStr);
 75	    
 76	    // Add interval for next slot
 77	    currentTime.setMinutes(currentTime.getMinutes() + appointmentInterval);
 78	  }
 79	  
 80	  return slots;
 81	}
 82	
 83	/**
 84	 * Filter slots by availability (removes booked slots)
 85	 * @param {string[]} slots - Array of time slots in format HH:MM
 86	 * @param {Object[]} existingAppointments - Array of existing appointments
 87	 * @param {string} date - Date string in format YYYY-MM-DD
 88	 * @param {string} workerId - Worker ID to check appointments for
 89	 * @returns {string[]} - Array of available time slots
 90	 */
 91	export function filterAvailableSlots(slots, existingAppointments, date, workerId) {
 92	  if (!existingAppointments || !existingAppointments.length) {
 93	    return slots;
 94	  }
 95	  
 96	  // Get appointments for this worker and date
 97	  const appointments = existingAppointments.filter(app => 
 98	    app.worker_id === workerId && 
 99	    app.date === date && 
100	    app.status !== 'cancelled'
101	  );
102	  
103	  if (!appointments.length) {
104	    return slots; // No appointments, all slots available
105	  }
106	  
107	  // Filter out booked slots
108	  return slots.filter(slot => {
109	    // Check for overlap with any existing appointment
110	    return !appointments.some(app => {
111	      const appointmentStart = app.start_time;
112	      const appointmentEnd = addMinutes(app.start_time, app.duration || 30);
113	      
114	      // Check if slot is within an existing appointment
115	      return slot >= appointmentStart && slot < appointmentEnd;
116	    });
117	  });
118	}
119	
120	/**
121	 * Generate a unique appointment ID
122	 * @returns {string} - Unique ID for the appointment
123	 */
124	function generateAppointmentId() {
125	  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
126	}
127	
128	/**
129	 * Get the duration for a service based on configuration
130	 * @param {string} serviceName - Name of the service
131	 * @param {Object} config - Application configuration
132	 * @returns {number} - Duration in minutes
133	 */
134	function getDurationForService(serviceName, config) {
135	  // Check if service exists in configuration
136	  const service = config?.services?.items?.find(
137	    item => item.name === serviceName
138	  );
139	  
140	  // Return service duration or default
141	  return service?.duration || config?.business?.appointmentDuration || 30;
142	}

