    console.log(`Created JS Date: ${jsDate.toDateString()}`); // Show the full date for debugging

    // Determine business hours based on day of week
    let businessHours;

    console.log(`Day of week for ${date} is ${dayOfWeek} (0=Sunday, 1=Monday, etc.)`);

    if (dayOfWeek === 0) { // Sunday
      // If no valid Sunday hours format, use empty string (closed)
      businessHours = (config?.business?.sundayHours && config.business.sundayHours.includes('-')) 
        ? config.business.sundayHours 
        : '';
      console.log("Using Sunday hours:", businessHours);
