          // Create confirmation message with these reliably stored values
          const confirmQuestion = `Para confirmar, você deseja ${servicePhrase} com ${safeWorker.name} no dia ${formattedDate} às ${selectedTime}. Está correto?`;
          const confirmOptions = "1. Sim\n2. Não";

