          step: 3
        }));

        // For individual accounts, auto-assign the solo worker and jump to date
        if (!isEnterpriseAccount) {
          const solo = workers[0] || {
            worker_id: sessionStorage.getItem('workerId'),
            name: sessionStorage.getItem('workerName')
          };
