      const timeSlots = ['09:00', '09:30', '10:00', '10:30', '11:00'];
      const date = '2025-05-15';
      const workerId = 'worker-1';

      const appointments = [
        // Cancelled appointment - should not affect availability
        {
          worker_id: 'worker-1',
          date: '2025-05-15',
          start_time: '09:00',
