    const workerId = bookingState.selectedWorker?.worker_id;

    if (!workerId) {
      console.log('Worker not selected yet');
      return;
    }

    // Update booking context with selected date
    console.log(`🛑 Setting new booking state with date: ${dateOption.value}`);
    setBookingState(prev => ({
      ...prev,
      selectedDate: dateOption.value,
      step: 5 // Move to the time selection step
    }));

    // Generate time options for this worker and date
    console.log(`🛑 Will generate times for date ${dateOption.value} and worker ${bookingState.selectedWorker?.name} (ID: ${workerId})`);

    // Clear any previous time options
    setAvailableTimes([]);

    // Generate time options for the selected date and worker
    generateTimeOptions(workerId, dateOption.value)
      .then(() => {
        // If no time slots are available, we'll handle it in formatTimeOptionsMessage
        if (availableTimes.length === 0) {
          console.log(`No time slots available for ${dateOption.display}`);
        }

        // Display the time options message
        const question = `Qual horário você prefere no dia ${dateOption.display}?`;
        const timeOptionsMessage = formatTimeOptionsMessage();

        // Add selected date and time options message
        setMessages(prev => [
          ...prev, 
          { role: 'user', content: dateOption.display },
          { role: 'assistant', content: question + "\n\n" + timeOptionsMessage }
        ]);
      })
      .catch(error => {
        console.error('Error generating time options:', error);
        setMessages(prev => [
          ...prev,
          { role: 'user', content: dateOption.display },
          { role: 'assistant', content: 'Desculpe, houve um erro ao buscar os horários disponíveis.' }
        ]);
      });
  };

