            const hasOverlap = (
              // Standard overlap detection
              (timeSlotMinutes < apptEndMinutes && timeSlotEndMinutes > apptStartMinutes)
            );

            // If there's no significant overlap (less than 5 minutes), still allow the slot
            if (hasOverlap) {
              // Calculate the actual overlap in minutes
              const overlapStart = Math.max(timeSlotMinutes, apptStartMinutes);
              const overlapEnd = Math.min(timeSlotEndMinutes, apptEndMinutes);
              const overlapMinutes = overlapEnd - overlapStart;

              // If the overlap is minimal (less than 5 minutes), don't consider it a conflict
              if (overlapMinutes < 5) {
                console.log(`Ignoring minimal overlap of ${overlapMinutes} minutes with appointment at ${appt.start_time}`);
                return false; // Not a significant conflict
              }
