            const appointmentDuration = appt.duration || 30;

            // Calculate start and end times in minutes since midnight
            const apptStartMinutes = apptHour * 60 + apptMinute;
            const apptEndMinutes = apptStartMinutes + appointmentDuration;

            // Check if there's an overlap between the two time ranges
            // Modified overlap detection to be more permissive of edge cases
            // A real overlap occurs when one range starts before the other ends
            // AND the first range ends after the second starts
            const hasOverlap = (
              // Standard overlap detection
              (timeSlotMinutes < apptEndMinutes && timeSlotEndMinutes > apptStartMinutes)
            );

            // If there's no significant overlap (less than 5 minutes), still allow the slot
            if (hasOverlap) {
              // Calculate the actual overlap in minutes
              const overlapStart = Math.max(timeSlotMinutes, apptStartMinutes);
              const overlapEnd = Math.min(timeSlotEndMinutes, apptEndMinutes);
              const overlapMinutes = overlapEnd - overlapStart;

