184	    }).join('\n');
185	    
186	    return `${header}\n\n${options}`;
187	  };
188	  
189	  // Helper function to format date options as a numbered list message
190	  const formatDateOptionsMessage = () => {
191	    console.log("Formatting date options message, availableDates:", availableDates?.length || 0);
192	    
193	    // If no available dates, generate them immediately
194	    if (!availableDates || availableDates.length === 0) {
195	      console.warn("Warning: No available dates available when formatting message! Generating now.");
196	      
197	      // Generate filtered dates
198	      const dates = generateDateOptions();
199	      
200	      // If we still don't have dates, create a message about it
201	      if (!dates || dates.length === 0) {
202	        return 'Não há datas disponíveis no momento. Por favor, tente novamente mais tarde.';
203	      }
204	      
205	      // *** MATCHING WHATSAPP BEHAVIOR ***
206	      // Since WhatsApp expects YYYY-MM-DD format for dates, we'll change the instruction
207	      const header = 'Escolha uma data digitando diretamente no formato AAAA-MM-DD:';
208	      const options = dates.map((date, index) => 
209	        `${index + 1}. ${date.display} (${date.value})`
210	      ).join('\n');
211	      const note = 'IMPORTANTE: Digite a data no formato AAAA-MM-DD (exemplo: 2025-05-15)';
212	      
213	      return `${header}\n\n${options}\n\n${note}`;
214	    }
215	    
216	    // *** MATCHING WHATSAPP BEHAVIOR ***
217	    // Since WhatsApp expects YYYY-MM-DD format for dates, we'll change the instruction
218	    const header = 'Escolha uma data digitando diretamente no formato AAAA-MM-DD:';
219	    
220	    // Use the FILTERED availableDates directly
221	    // Make a copy to avoid race conditions
222	    const filteredDates = [...availableDates];
223	    console.log(`Displaying ${filteredDates.length} filtered dates`);
224	    
225	    // Format options from filtered availableDates
226	    const options = filteredDates.map((date, index) => 
227	      `${index + 1}. ${date.display} (${date.value})`
228	    ).join('\n');
229	    
230	    const note = 'IMPORTANTE: Digite a data no formato AAAA-MM-DD (exemplo: 2025-05-15)\n\n* Somente datas com horários disponíveis são mostradas.';
231	    
232	    console.log("Generated date options message with", filteredDates.length, "FILTERED options");
233	    return `${header}\n\n${options}\n\n${note}`;
234	  };
235	  
236	  // Helper function to format time options as a numbered list message
237	  const formatTimeOptionsMessage = () => {
238	    // CRITICAL FIX: Make a local copy of availableTimes to prevent race conditions
239	    const times = [...availableTimes];
240	    
241	    // Check if availableTimes is defined and has elements
242	    if (!times || !Array.isArray(times) || times.length === 0) {
243	      console.log("No available times found when formatting time options message");
244	      
245	      // Get the date display for the current selection
246	      const selectedDateObject = availableDates.find(d => d.value === bookingState.selectedDate);
247	      const dateDisplay = selectedDateObject ? selectedDateObject.display : bookingState.selectedDate;
248	      
249	      // Show dates again automatically
250	      setTimeout(() => {
251	        generateDateOptions();
252	        const dateOptionsMsg = formatDateOptionsMessage();
253	        setMessages(prev => [...prev, { 
254	          role: 'assistant', 
255	          content: 'Por favor, escolha outra data para seu agendamento:\n\n' + dateOptionsMsg 
256	        }]);
257	      }, 500);
258	      
259	      return `Não há horários disponíveis para ${dateDisplay}. Gostaria de escolher outra data?`;
260	    }
261	    
262	    // For debugging - log each time entry to see its structure
263	    if (times.length > 0) {
264	      console.log("Time entries structure:", 
265	        typeof times[0], 
266	        JSON.stringify(times[0]).substring(0, 50),
267	        `(${times.length} total filtered times)`
268	      );
269	    }
270	    
271	    // *** MATCHING WHATSAPP BEHAVIOR ***
272	    // Since WhatsApp expects HH:MM format for times, we'll change the instruction
273	    // to match that behavior and avoid confusion
274	    const header = 'Escolha um horário digitando diretamente no formato HH:MM:';
275	    
276	    // Determine if we need to split the display to avoid too long a message
277	    const MAX_TIMES_TO_SHOW = 15; // Reasonable number for chat display
278	    
279	    // If we have more times than the max, we'll group them by hour
280	    let formattedOptions;
281	    
282	    if (times.length > MAX_TIMES_TO_SHOW) {
283	      console.log(`Grouping ${times.length} times by hour for more compact display`);
284	      
285	      // Group times by hour to make display more manageable
286	      const timesByHour = {};
287	      
288	      times.forEach(time => {
289	        const timeStr = typeof time === 'object' && time.formatted ? time.formatted : String(time);
290	        const hour = timeStr.split(':')[0];
291	        if (!timesByHour[hour]) {
292	          timesByHour[hour] = [];
293	        }
294	        timesByHour[hour].push(timeStr);
295	      });
296	      
297	      // Generate summary by hour
298	      const hourSummaries = Object.keys(timesByHour).map((hour, index) => {
299	        const count = timesByHour[hour].length;
300	        const firstTime = timesByHour[hour][0];
301	        const lastTime = timesByHour[hour][count - 1];
302	        return `${index + 1}. ${hour}h: ${firstTime} - ${lastTime} (${count} opções)`;
303	      });
304	      
305	      formattedOptions = hourSummaries.join('\n');
306	      
307	      // Change instruction to select an hour first
308	      const note = 'IMPORTANTE: Digite o horário completo no formato HH:MM (exemplo: 14:30).\n\nOs horários estão agrupados por hora para facilitar a visualização.';
309	      return `${header}\n\n${formattedOptions}\n\n${note}`;
310	    } else {
311	      // For smaller lists, just show the times directly
312	      const timesToShow = times.map((time, index) => {
313	        // Handle both string and object time formats
314	        const timeStr = typeof time === 'object' && time.formatted ? time.formatted : String(time);
315	        return `${index + 1}. ${timeStr}`;
316	      });
317	      
318	      formattedOptions = timesToShow.join('\n');
319	      const note = 'IMPORTANTE: Digite o horário no formato HH:MM (exemplo: 14:30)';
320	      
321	      return `${header}\n\n${formattedOptions}\n\n${note}`;
322	    }
323	  };
324	  
325	  // Use the config from the component scope
326	  const getPromptText = () => {
327	    // Use the config already defined at the component level
328	    // No need to call useConfig() again
329	    
330	    const businessType = config?.business?.type?.toUpperCase() || 'BARBEARIA';
