            } else if (dayOfWeek === 0) { // Sunday
              isOpen = !!config?.business?.sundayHours;
            } else if (dayOfWeek === 6) { // Saturday
              isOpen = !!config?.business?.saturdayHours;
            } else { // Weekday
              isOpen = !!config?.business?.weekdayHours;
