 28	// Mock function to test business hours determination
 29	function determineBusinessHours(dayOfWeek, config) {
 30	  let businessHours;
 31	  
 32	  if (dayOfWeek === 0) { // Sunday
 33	    businessHours = (config?.business?.sundayHours && config.business.sundayHours.includes('-')) 
 34	      ? config.business.sundayHours 
 35	      : '';
 36	  } else if (dayOfWeek === 6) { // Saturday
