 38	      ? config.business.saturdayHours 
 39	      : '08:00-14:00';
 40	  } else { // Weekdays (Monday-Friday)
 41	    // Try to get from config, with a fallback to openHours-closeHours if those exist
 42	    if (config?.business?.weekdayHours && config.business.weekdayHours.includes('-')) {
 43	      businessHours = config.business.weekdayHours;
 44	    } 
 45	    // Try to use openHours and closeHours if they exist in the config
 46	    else if (config?.business?.openHours && config?.business?.closeHours) {
 47	      businessHours = `${config.business.openHours}-${config.business.closeHours}`;
 48	    }
 49	    // Default if nothing else available
 50	    else {
 51	      businessHours = '08:00-18:00';
 52	    }
 53	  }
 54	  
