 59	function generateTimeSlots(config, date, interval) {
 60	  const businessHours = determineBusinessHours(testDayOfWeekCalculation(date).dayOfWeek, config);
 61	  
 62	  if (!businessHours) {
 63	    return [];
 64	  }
 65	  
 66	  const [openTime, closeTime] = businessHours.split('-');
 67	  if (!openTime || !closeTime) {
 68	    return [];
 69	  }
 70	  
 71	  const [startHour, startMinute] = openTime.split(':').map(Number);
 72	  const [endHour, endMinute] = closeTime.split(':').map(Number);
 73	  
 74	  const useInterval = interval || config?.chatbot?.timeInterval || 
 75	                     config?.business?.appointmentInterval || 30;
 76	  
 77	  const slots = [];
 78	  let currentHour = startHour;
 79	  let currentMinute = startMinute;
 80	  
 81	  while (currentHour < endHour || (currentHour === endHour && currentMinute < endMinute)) {
 82	    const formattedHour = currentHour.toString().padStart(2, '0');
 83	    const formattedMinute = currentMinute.toString().padStart(2, '0');
 84	    const timeSlot = `${formattedHour}:${formattedMinute}`;
 85	    
 86	    slots.push(timeSlot);
 87	    
 88	    currentMinute += useInterval;
 89	    if (currentMinute >= 60) {
 90	      currentHour += 1;
 91	      currentMinute -= 60;
 92	    }
 93	  }
 94	  
 95	  return slots;
 96	}
