 98	// Mock function to test improved conflict detection
 99	function hasTimeConflict(slotStart, slotDuration, apptStart, apptDuration) {
100	  // Parse time strings to minutes since midnight
101	  const parseTime = (timeStr) => {
102	    const [hours, minutes] = timeStr.split(':').map(Number);
103	    return hours * 60 + minutes;
104	  };
105	  
106	  const slotStartMinutes = parseTime(slotStart);
107	  const slotEndMinutes = slotStartMinutes + slotDuration;
108	  
109	  const apptStartMinutes = parseTime(apptStart);
110	  const apptEndMinutes = apptStartMinutes + apptDuration;
111	  
112	  // Standard overlap detection - one range starts before the other ends
113	  const hasOverlap = (
114	    slotStartMinutes < apptEndMinutes && 
115	    slotEndMinutes > apptStartMinutes
116	  );
117	  
118	  // If there's overlap, check if it's significant (> 5 minutes)
119	  if (hasOverlap) {
120	    const overlapStart = Math.max(slotStartMinutes, apptStartMinutes);
121	    const overlapEnd = Math.min(slotEndMinutes, apptEndMinutes);
122	    const overlapMinutes = overlapEnd - overlapStart;
123	    
124	    // Ignore minimal overlaps
125	    if (overlapMinutes < 5) {
126	      return false;
127	    }
128	  }
129	  
130	  return hasOverlap;
131	}
