133	// Mock function to test time options formatting
134	function formatTimeOptions(times, MAX_TIMES_TO_SHOW = 15) {
135	  if (!times || !Array.isArray(times) || times.length === 0) {
136	    return 'No available times.';
137	  }
138	  
139	  // If we have more times than the max, we'll group them by hour
140	  if (times.length > MAX_TIMES_TO_SHOW) {
141	    // Group times by hour to make display more manageable
142	    const timesByHour = {};
143	    
144	    times.forEach(time => {
145	      const hour = time.split(':')[0];
146	      if (!timesByHour[hour]) {
147	        timesByHour[hour] = [];
148	      }
149	      timesByHour[hour].push(time);
150	    });
151	    
152	    // Generate summary by hour
153	    const hourSummaries = Object.keys(timesByHour).map((hour, index) => {
154	      const count = timesByHour[hour].length;
155	      const firstTime = timesByHour[hour][0];
156	      const lastTime = timesByHour[hour][count - 1];
157	      return `${index + 1}. ${hour}h: ${firstTime} - ${lastTime} (${count} options)`;
158	    });
159	    
160	    return hourSummaries.join('\n');
161	  } else {
162	    // For smaller lists, just show the times directly
163	    const timesToShow = times.map((time, index) => 
164	      `${index + 1}. ${time}`
165	    );
166	    
167	    return timesToShow.join('\n');
168	  }
169	}
