      // CRITICAL: First save all current state to variables before any state updates
      // This prevents race conditions where state might change during the update
      const currentDate = bookingState.selectedDate;
      const currentWorker = bookingState.selectedWorker;
      const currentService = bookingState.selectedService;
      const currentDuration = bookingState.customDuration || 30;

      console.log(`🔍 handleTimeSelect called with time: ${time}`);
      console.log(`🔍 Current state BEFORE update:`);
      console.log(`🔍 - Date: ${currentDate}`);
      console.log(`🔍 - Worker: ${currentWorker?.name}`);
      console.log(`🔍 - Service: ${currentService}`);

      // CRITICAL FIX: Create a complete state object instead of using functional update
      // This ensures we set all fields explicitly and don't rely on the previous state
      const updatedState = {
        ...bookingState,
        selectedTime: time,
        // EXPLICITLY set these critical fields to ensure they don't change
        selectedDate: currentDate,
        selectedWorker: currentWorker,
        selectedService: currentService,
        customDuration: currentDuration,
        step: 6
      };

      // Log what we're about to set
      console.log(`🔍 Setting updated state with preserved date: ${updatedState.selectedDate}`);

      // Update the booking state with our complete object
      setBookingState(updatedState);

      // Add this selection to chat messages only if requested
      if (addToMessages) {
        setMessages(prev => [
          ...prev, 
          { role: 'user', content: time }
        ]);
      }

      // Format date for display in dd/mm/yyyy format - using our explicitly saved currentDate
      console.log(`🔍 Formatting confirmation date from saved value: ${currentDate}`);
      const [y, m, d] = currentDate.split('-').map(Number);
      const selectedDate = new Date(y, m - 1, d);    // use this to fix the CGR UTC-4 bug
      const day = selectedDate.getDate().toString().padStart(2, '0');
      const month = (selectedDate.getMonth() + 1).toString().padStart(2, '0');
      const year = selectedDate.getFullYear();
      const formattedDate = `${day}/${month}/${year}`;
      console.log(`🔍 Formatted date for confirmation: ${formattedDate}`);

      // Create confirmation message with or without service details - USE OUR SAVED VALUES
      const servicePhrase = currentService === 'Consulta' 
        ? `agendar uma consulta de ${currentDuration} minutos` 
        : `agendar ${currentService}`;

      console.log(`🔍 Generating confirmation with:`);
      console.log(`🔍 - Worker: ${currentWorker?.name}`);
      console.log(`🔍 - Date: ${formattedDate}`);
      console.log(`🔍 - Time: ${time}`);
      console.log(`🔍 - Service: ${currentService}`);

      // Add assistant response for confirmation with yes/no options
      const confirmQuestion = `Para confirmar, você deseja ${servicePhrase} com ${currentWorker.name} no dia ${formattedDate} às ${time}. Está correto?`;
      const confirmOptions = "1. Sim\n2. Não";
      const assistantResponse = { 
        role: 'assistant', 
        content: confirmQuestion + "\n\n" + confirmOptions
      };

      // Use a small timeout to ensure state update happens first
      setTimeout(() => {
        setMessages(prev => [...prev, assistantResponse]);
      }, 50);
    } else {
      // In free mode, just send as a message
      setInput(time);
      sendMessage(time);
    }
  };


  // Helper function to download ICS file
  const downloadIcsFile = (appointmentId) => {
    if (window.icsUrls && window.icsUrls[appointmentId]) {
      // Create a temporary link element
      const downloadLink = document.createElement('a');
      downloadLink.href = window.icsUrls[appointmentId];
      downloadLink.download = `appointment_${appointmentId}.ics`;

      // Append to body, click, and remove
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);

      // Send confirmation message
      const confirmMessage = {
        role: 'assistant',
        content: '📅 Arquivo do calendário enviado! O download deve começar automaticamente. Salve o arquivo e importe-o para o Google Calendar, Outlook ou Apple Calendar.'
      };
      setMessages(prev => [...prev, confirmMessage]);

      // Revoke the URL to free memory
      setTimeout(() => {
        URL.revokeObjectURL(window.icsUrls[appointmentId]);
        delete window.icsUrls[appointmentId];
      }, 5000);
    } else {
      // Handle case where ICS file is not available
      const errorMessage = {
        role: 'assistant',
        content: '❌ Desculpe, não foi possível gerar o arquivo do calendário. Por favor, tente novamente ou adicione o agendamento manualmente ao seu calendário.'
      };
      setMessages(prev => [...prev, errorMessage]);
    }
  };

  const sendMessage = async (messageText = null) => {
    const textToSend = messageText || input;
    if (!textToSend.trim()) return;

    // Grab the fresh step value
    const currentStep = ctx.step;

    const userMessage = { role: 'user', content: textToSend };

    if (isGuidedMode()) {
      // First, ensure that all available dates are generated immediately
      if (currentStep === 4 && !availableDates.length) {
        console.log("Generating dates immediately since we're at date selection step");
        generateDateOptions();
      }

      // Check for number selections in different steps
      const numMatch = textToSend.trim().match(/^[0-9]+$/);
      if (numMatch) {
        const num = parseInt(numMatch[0], 10);

        // ——— TIME SELECTION BY NUMBER ———
        if (currentStep === 5 && availableTimes.length >= num && num > 0) {
          // Show the raw input (the number) in the UI
          setMessages(prev => [...prev, { role: 'user', content: textToSend }]);

          // Clear input
          setInput('');

          // Pick the nth time from the array
          handleTimeSelect(availableTimes[num - 1], false); // false = don't add message
          return;
        }

        // Handle service selection by number
        if (currentStep === 2 && commonServices.length >= num && num > 0) {
          const selectedService = commonServices[num - 1];

          // Show the raw input (the number) in the UI, not the service name
          setMessages(prev => [...prev, { role: 'user', content: textToSend }]);

          // Clear input
          setInput('');

          // Process the selection in the background (without adding another message)
          handleServiceSelect(selectedService, false); // false = don't add to messages
          return;
        }

        // Handle worker selection by number
        else if (ctx.step === 3 && workers.length >= num && num > 0) {
          const selectedWorker = workers[num - 1];

          // Show the raw input (the number) in the UI, not the worker name
          setMessages(prev => [...prev, { role: 'user', content: textToSend }]);

          // Clear input
          setInput('');

          // Process the selection in the background (without adding another message)
          handleWorkerSelect(selectedWorker, false); // false = don't add to messages
          return;
        }

        // Handle date selection by number - WITH DEBUGGING
        else if (ctx.step === 4 && availableDates.length >= num && num > 0) {
          const selectedDate = availableDates[num - 1];

          // DEBUGGING
          console.log(`🔍 DATE SELECTION BY NUMBER: ${num}`);
