    const dayOfWeek = jsDate.getDay();

    console.log(`Determining hours for ${date}, which is day ${dayOfWeek} (0=Sun, 1=Mon, etc.)`);

    // Determine business hours based on day of week
    let businessHours;

    if (dayOfWeek === 0) { // Sunday
